type pureSources struct {
	bytes map[string][]byte
	refs  []execute.SourceReference
}

func (s *pureSources) ReadSource(ctx context.Context, ref execute.SourceReference) ([]byte, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	data, ok := s.bytes[ref.Reference]
	if !ok || !((ref.Name == "browser" && ref.Type == "browser-profile") || (ref.Name == "authentication" && ref.Type == "browser-authentication")) {
		return nil, errors.New("source outside exact in-memory fixture")
	}
	s.refs = append(s.refs, ref)
	return bytes.Clone(data), nil
}

