func readInput(t *testing.T, name string) []byte {
	t.Helper()
	raw, err := os.ReadFile("synthetic-inputs/" + name)
	if err != nil {
		t.Fatal(err)
	}
	return raw
}

func newJointFixture(t *testing.T, version, timeout string) *jointFixture {
	t.Helper()
	timing := ""
	if timeout != "" {
		timing = "    timeout: " + timeout + "\n"
	}
	authPath := "sources/browser-profile/authentication-" + version + ".json"
	actionPath := "sources/browser-profile/action-1.10.json"
	workflow := fmt.Sprintf(`uws: 1.13.0
info: {title: P12 synthetic pure compatibility, version: '1'}
sourceDescriptions: [{name: browser, type: browser-profile, url: %s}]
operations:
  - operationId: auth
    effect: write
%s    x-uws-operation-profile: uws.browser-authentication-call.%s
    x-uws-browser-authentication:
      profile: %s
      flow: login
      session: member
      credentialBindings: {}
  - operationId: read
    sourceDescription: browser
    sourceOperationId: read_status
    effect: read
    x-uws-browser-session: {session: member}
    outputs: {count: '$response.body#/result_count'}
  - operationId: write
    sourceDescription: browser
    sourceOperationId: save_status
    effect: write
    x-uws-browser-session: {session: member}
workflows:
  - workflowId: main
    type: sequence
    steps: [{stepId: auth-step, operationRef: auth}, {stepId: read-step, operationRef: read}, {stepId: write-step, operationRef: write}]
`, actionPath, timing, version, authPath)
	o := packagev3.BuildOptions{Scope: "workflows/W01-p12-source-fixture", WorkflowYAML: []byte(workflow), DataJSON: readInput(t, "data.json"), Sources: []packagev3.SourceInput{
		{ID: "authentication", Kind: "browser-profile", Path: authPath, Bytes: readInput(t, "authentication-"+version+".json")},
		{ID: "browser", Kind: "browser-profile", Path: actionPath, Bytes: readInput(t, "action-1.10.json")},
	}}
	p, err := packagev3.Build(context.Background(), o)
	if err != nil {
		t.Fatal("Build", err)
	}
	a, err := packagev3.Assess(context.Background(), p.Manifest, p.Files)
	if err != nil || !reflect.DeepEqual(a, p.Assessment) || a.Outcome == "incompatible" {
		t.Fatal("Assess", a, err)
	}
	v, err := packagev3.Verify(context.Background(), packagev3.VerifyOptions{Scope: o.Scope, ExpectedSHA256: p.SHA256, Files: p.Files})
	if err != nil {
		t.Fatal("Verify", err)
	}
	if !bytes.Equal(v.Snapshot()[packagev3.WorkflowPath], o.WorkflowYAML) || !bytes.Equal(v.Snapshot()[packagev3.DataPath], o.DataJSON) {
		t.Fatal("public bytes changed")
	}
	s, err := v.BrowserSupplement()
	if err != nil || len(s.Calls) != 3 || s.WorkflowSHA256 != browsercontract.SHA256(o.WorkflowYAML) {
		t.Fatal("complete supplement", err)
	}
	for i, kind := range []string{"authentication", "action", "action"} {
		if s.Calls[i].Kind != kind || s.Calls[i].SessionName != "member" || s.Calls[i].ReuseAllowed || s.Calls[i].SaveAllowed {
			t.Fatal("unexpected inventory or permissions")
		}
	}
	f := &jointFixture{t: t, options: o, packageBytes: p, verified: v}
	t.Cleanup(func() {
		if f.effects.calls != 0 {
			t.Errorf("effect callbacks=%d, want zero", f.effects.calls)
		}
	})
	return f
}

func (f *jointFixture) nativeHost(planSHA, receiptSHA string) (execute.Host, *pureSources) {
	f.t.Helper()
	snapshot := f.verified.Snapshot()
	supplement, err := f.verified.BrowserSupplement()
	if err != nil {
		f.t.Fatal(err)
	}
	sources := &pureSources{bytes: map[string][]byte{}}
	paths := map[string]string{}
	for _, source := range supplement.Sources {
		paths[source.ID] = source.Artifact.Path
		sources.bytes[source.Artifact.Path] = bytes.Clone(snapshot[source.Artifact.Path])
	}
	d := strings.Repeat("a", 64)
	closure := execute.BrowserClosure{
		WorkerModule: "p12.joint-fixture", WorkerProfile: "p12.offline.exec.v1", WorkerRevision: nativeRevision, WorkerBinarySHA256: d,
		WorkerClosureSHA256: strings.Repeat("b", 64), DriverRevision: strings.Repeat("d", 40), DriverClosureSHA256: strings.Repeat("e", 64), DriverLockSHA256: d, DriverBinarySHA256: d,
		NodeVersion: "24.14.1", NodeBinarySHA256: d, PlaywrightVersion: "1.62.1", PlaywrightClosureSHA256: d,
		ChromiumVersion: "151.0.7922.34", ChromiumRevision: "1234", ChromiumBinarySHA256: d, Sandbox: true,
	}
	binding := execute.BrowserPlanBinding{OwnerID: "owner", AgentID: "agent", RunID: "run", WorkflowID: "main", WorkflowSHA256: browsercontract.SHA256(snapshot[packagev3.WorkflowPath]), PackageSHA256: f.verified.SHA256(), InputsSHA256: f.packageBytes.Assessment.InputsSHA256, PlanSHA256: planSHA, ApprovalReceiptSHA256: receiptSHA, AdmittedDeadline: originalDeadline}
	for _, call := range supplement.Calls {
		path := paths[call.SourceID]
		table, err := browsertools.BuildBrowserShapeTable(context.Background(), browsertools.BrowserShapeOptions{Sources: []browsertools.BrowserShapeSourceInput{{ID: call.SourceID, URL: path, Content: sources.bytes[path]}}})
		if err != nil {
			f.t.Fatal("independent shape", err)
		}
		leaf := execute.BrowserLeaf{StepID: call.StepID, OperationID: call.OperationID, InvocationID: call.InvocationID, Purpose: call.Kind, SourceID: call.SourceID, SourceSHA256: call.SourceSHA256, ProfileVersion: call.ProfileVersion, SelectedSHA256: call.SelectedSHA256, SessionName: call.SessionName, OuterProtocol: call.OuterProtocol, InnerProtocol: call.InnerProtocol, Origins: append([]string{}, call.Origins...)}
		found := false
		for _, op := range table.Operations {
			if op.Selector.Key != call.Selector.Key {
				continue
			}
			shape := op.Browser
			if shape == nil || shape.SelectedSHA256 != call.SelectedSHA256 || table.Sources[0].SHA256 != call.SourceSHA256 || !bytes.Equal(shape.Effects, call.Effects) {
				f.t.Fatal("selected shape provenance")
			}
			leaf.NativeEffects = bytes.Clone(shape.Effects)
			leaf.ConfirmationPolicy = bytes.Clone(shape.ConfirmationPolicy)
			found = true
		}
		if !found {
			f.t.Fatal("missing selected shape")
		}
		if call.Kind == "authentication" {
			leaf.Flow = call.Selector.Key
			leaf.AuthenticationSourceID, leaf.AuthenticationSHA256 = leaf.SourceID, leaf.SourceSHA256
			if len(leaf.ConfirmationPolicy) != 0 || call.AuthenticationSourceID != "" {
				f.t.Fatal("authentication absence/self-binding changed")
			}
		} else {
			leaf.ActionKey = call.Selector.Key
			leaf.AuthenticationSourceID, leaf.AuthenticationSHA256 = binding.Inventory[0].SourceID, binding.Inventory[0].SourceSHA256
			if call.AuthenticationSourceID != leaf.AuthenticationSourceID || len(leaf.ConfirmationPolicy) == 0 {
				f.t.Fatal("action authentication/policy binding")
			}
		}
		binding.Inventory = append(binding.Inventory, leaf)
	}
	var inputs map[string]any
	if json.Unmarshal(snapshot[packagev3.DataPath], &inputs) != nil {
		f.t.Fatal("data projection")
	}
	return execute.Host{Inputs: inputs, Sources: sources, Browser: &execute.BrowserOptions{Executable: "/p12-fixture/never-launch", Closure: closure, Binding: binding, Host: &f.effects, Interaction: &f.effects}}, sources
}

func (f *jointFixture) nativeCompile(ctx context.Context, planSHA, receiptSHA string) (*runtimeplan.Plan, execute.Host, error) {
	f.t.Helper()
	host, reads := f.nativeHost(planSHA, receiptSHA)
	workflow := f.verified.Snapshot()[packagev3.WorkflowPath]
	if browsercontract.SHA256(workflow) != host.Browser.Binding.WorkflowSHA256 {
		f.t.Fatal("native workflow byte digest")
	}
	doc, _, err := packagev3.DecodeWorkflow(ctx, workflow)
	if err != nil {
		f.t.Fatal(err)
	}
	plan, err := execute.Compile(ctx, doc, host)
	f.lastSourceReads = len(reads.refs)
	if err != nil {
		f.t.Logf("pure Compile refusal=%v source_reads=%d", err, f.lastSourceReads)
		return nil, host, err
	}
	err = execute.CheckSupported(ctx, execute.Request{Plan: plan}, host)
	if len(reads.refs) != f.lastSourceReads {
		f.t.Fatal("CheckSupported read sources")
	}
	if f.lastSourceReads != 2 {
		f.t.Fatal("native Compile did not read the exact two sources", f.lastSourceReads)
	}
	return plan, host, err
}

func (f *jointFixture) execution() packagev3.ExecutionOptions {
	return packagev3.ExecutionOptions{Worker: packagev3.WorkerIdentity{BinarySHA256: strings.Repeat("a", 64), ClosureSHA256: strings.Repeat("b", 64), RuntimeRevision: nativeRevision}, RuntimeAdmission: func(ctx context.Context, r packagev3.RuntimeAdmissionRequest) error {
		f.admissions++
		snapshot := f.verified.Snapshot()
		if r.RuntimeRevision != nativeRevision || !bytes.Equal(r.WorkflowYAML, snapshot[packagev3.WorkflowPath]) || !bytes.Equal(r.DataJSON, snapshot[packagev3.DataPath]) || len(r.Sources) != len(f.options.Sources) {
			f.t.Fatal("admission did not receive exact verified workflow/data/source inventory")
		}
		for _, source := range f.options.Sources {
			if !bytes.Equal(r.Sources[source.Path], snapshot[source.Path]) {
				f.t.Fatal("admission source bytes changed")
			}
		}
		// Plan/receipt do not exist yet. These explicit preparation hashes grant
		// nothing. Finalized actual plan/receipt binding is checked separately.
		_, _, err := f.nativeCompile(ctx, browsercontract.SHA256([]byte("P12 preparation plan; no authority")), browsercontract.SHA256([]byte("P12 preparation receipt; no authority")))
		f.lastAdmission = err
		return err
	}}
}

func (f *jointFixture) finalized(execution packagev3.ExecutionOptions, plan packagev3.ExecutionPlan) (packagev3.BrowserAuthorityOptions, browsercontract.BrowserAuthorityV1) {
	f.t.Helper()
	supplement, err := f.verified.BrowserSupplement()
	if err != nil {
		f.t.Fatal(err)
	}
	origins := []string{}
	for _, call := range supplement.Calls {
		origins = append(origins, call.Origins...)
	}
	slices.Sort(origins)
	origins = slices.Compact(origins)
	c := browsercontract.BrowserConfigV1{Version: browsercontract.ConfigVersion, OwnerID: "owner", AgentID: "agent", RunID: "run", PackageSHA256: f.verified.SHA256(), HandoffSHA256: plan.HandoffSHA256, InputsSHA256: plan.InputsSHA256, ApprovalSHA256: strings.Repeat("f", 64), PlanSHA256: plan.PlanSHA256, WorkflowSHA256: f.packageBytes.Manifest.Workflow.SHA256, SupplementSHA256: f.packageBytes.Manifest.Browser.SHA256, Worker: browsercontract.BrowserWorkerV1{Profile: "p12.offline.exec.v1", BinarySHA256: execution.Worker.BinarySHA256, ClosureSHA256: execution.Worker.ClosureSHA256, RuntimeRevision: execution.Worker.RuntimeRevision}, DriverClosureSHA256: strings.Repeat("e", 64), LaunchNonce: "synthetic-launch", ContainmentLeaseID: "synthetic-containment", AdmittedDeadline: originalDeadline.Format(time.RFC3339Nano), Origins: origins, ApprovedCalls: supplement.Calls, CredentialRevisions: []browsercontract.CredentialRevision{}, HostFactRefs: []string{"synthetic:p12-offline-host"}}
	record, err := approval.ReviewBrowserConfig(c, "2026-10-13T00:00:00Z")
	if err != nil {
		f.t.Fatal("review receipt", err)
	}
	receipt, err := record.CanonicalBytes()
	if err != nil {
		f.t.Fatal(err)
	}
	c.ApprovalSHA256 = browsercontract.SHA256(receipt)
	if err := approval.CheckBrowserApproval(receipt, c); err != nil {
		f.t.Fatal("finalized receipt", err)
	}
	o := packagev3.BrowserAuthorityOptions{ExpectedConfig: c, FinalizedApproval: receipt, ConfirmedPlanSHA256: plan.PlanSHA256, Now: time.Date(2026, 10, 13, 0, 0, 1, 0, time.UTC)}
	a, err := packagev3.DeriveBrowserAuthority(context.Background(), f.verified, execution, o)
	if err != nil || a.Validate() != nil {
		f.t.Fatal("derive authority", err)
	}
	if err := packagev3.CheckBrowserAuthority(context.Background(), f.verified, execution, o, a); err != nil {
		f.t.Fatal("check authority", err)
	}
	return o, a
}

func TestP12PublicAndNativeExactBytesTimedAuthenticationReadWrite(t *testing.T) {
	for _, version := range []string{"1.0", "1.1"} {
		for _, timeout := range []string{"0.25", "30", "600"} {
			t.Run(version+"/"+timeout, func(t *testing.T) {
				f := newJointFixture(t, version, timeout)
				execution := f.execution()
				plan, err := packagev3.DeriveExecutionPlan(context.Background(), f.verified, execution)
				if err != nil || f.admissions != 1 || len(plan.Operations) != 3 {
					t.Fatal("derive admitted plan", err, "admissions", f.admissions, "native refusal", f.lastAdmission)
				}
				if err := packagev3.CheckExecutionPlan(context.Background(), f.verified, execution, plan); err != nil {
					t.Fatal("check plan", err)
				}
				o, a := f.finalized(execution, plan)
				native, host, err := f.nativeCompile(context.Background(), plan.PlanSHA256, o.ExpectedConfig.ApprovalSHA256)
				if err != nil || len(native.BrowserAuthenticationOperations()) != 1 || len(native.BrowserOperations()) != 2 {
					t.Fatal("finalized native binding", err)
				}
				if host.Browser.Binding.PlanSHA256 != plan.PlanSHA256 || host.Browser.Binding.ApprovalReceiptSHA256 != browsercontract.SHA256(o.FinalizedApproval) || host.Browser.Binding.AdmittedDeadline != originalDeadline {
					t.Fatal("finalized identities changed")
				}
				if !bytes.Equal(f.verified.Snapshot()[packagev3.WorkflowPath], f.options.WorkflowYAML) || !bytes.Equal(f.verified.Snapshot()[packagev3.DataPath], f.options.DataJSON) {
					t.Fatal("verification mutated exact bytes")
				}
				if f.effects.calls != 0 {
					t.Fatal("effects")
				}
				t.Logf("source-fixture version=%s timeout=%s workflow=%s package=%s inputs=%s handoff=%s constraints=%s plan=%s receipt=%s config=%s sources=%s,%s native=%s source_reads=%d admissions=%d effect_callbacks=0", version, timeout, host.Browser.Binding.WorkflowSHA256, f.verified.SHA256(), plan.InputsSHA256, plan.HandoffSHA256, plan.Operations[0].ConstraintsSHA256, plan.PlanSHA256, o.ExpectedConfig.ApprovalSHA256, a.ConfigSHA256, f.packageBytes.Manifest.Sources[0].Artifact.SHA256, f.packageBytes.Manifest.Sources[1].Artifact.SHA256, nativeRevision, f.lastSourceReads, f.admissions)
			})
		}
	}
}

func TestP12TimeoutSuccessorRefusesOldPlanReceiptConfigAuthorityAndTamper(t *testing.T) {
	for _, version := range []string{"1.0", "1.1"} {
		t.Run(version, func(t *testing.T) {
			old := newJointFixture(t, version, "30")
			fresh := newJointFixture(t, version, "31")
			oldExecution, freshExecution := old.execution(), fresh.execution()
			oldPlan, err := packagev3.DeriveExecutionPlan(context.Background(), old.verified, oldExecution)
			if err != nil {
				t.Fatal(err)
			}
			freshPlan, err := packagev3.DeriveExecutionPlan(context.Background(), fresh.verified, freshExecution)
			if err != nil {
				t.Fatal(err)
			}
			oldOptions, oldAuthority := old.finalized(oldExecution, oldPlan)
			freshOptions, _ := fresh.finalized(freshExecution, freshPlan)
			for name, pair := range map[string][2]string{"workflow": {old.packageBytes.Manifest.Workflow.SHA256, fresh.packageBytes.Manifest.Workflow.SHA256}, "package": {old.verified.SHA256(), fresh.verified.SHA256()}, "inputs": {oldPlan.InputsSHA256, freshPlan.InputsSHA256}, "handoff": {oldPlan.HandoffSHA256, freshPlan.HandoffSHA256}, "raw constraints": {oldPlan.Operations[0].ConstraintsSHA256, freshPlan.Operations[0].ConstraintsSHA256}, "plan": {oldPlan.PlanSHA256, freshPlan.PlanSHA256}} {
				if pair[0] == pair[1] {
					t.Fatal("timeout failed to change", name)
				}
			}
			for i := range oldPlan.Operations {
				if !reflect.DeepEqual(oldPlan.Operations[i].Browser, freshPlan.Operations[i].Browser) || !reflect.DeepEqual(oldPlan.Operations[i].Source, freshPlan.Operations[i].Source) {
					t.Fatal("timing changed independent source provenance")
				}
			}
			if packagev3.CheckExecutionPlan(context.Background(), fresh.verified, freshExecution, oldPlan) == nil {
				t.Fatal("old plan transferred")
			}
			staleConstraints := freshPlan
			staleConstraints.Operations = append([]packagev3.ExecutionOperation{}, freshPlan.Operations...)
			staleConstraints.Operations[0].ConstraintsSHA256 = oldPlan.Operations[0].ConstraintsSHA256
			staleConstraints.PlanSHA256 = staleConstraints.Digest()
			if packagev3.CheckExecutionPlan(context.Background(), fresh.verified, freshExecution, staleConstraints) == nil {
				t.Fatal("old rehashed constraints transferred")
			}
			oldConfig := oldOptions
			oldConfig.ConfirmedPlanSHA256 = freshPlan.PlanSHA256
			if _, err := packagev3.DeriveBrowserAuthority(context.Background(), fresh.verified, freshExecution, oldConfig); err == nil {
				t.Fatal("old config transferred")
			}
			oldReceipt := freshOptions
			oldReceipt.FinalizedApproval = oldOptions.FinalizedApproval
			oldReceipt.ExpectedConfig.ApprovalSHA256 = oldOptions.ExpectedConfig.ApprovalSHA256
			if approval.CheckBrowserApproval(oldReceipt.FinalizedApproval, oldReceipt.ExpectedConfig) == nil {
				t.Fatal("old receipt transferred")
			}
			if _, err := packagev3.DeriveBrowserAuthority(context.Background(), fresh.verified, freshExecution, oldReceipt); err == nil {
				t.Fatal("old receipt derived authority")
			}
			if packagev3.CheckBrowserAuthority(context.Background(), fresh.verified, freshExecution, freshOptions, oldAuthority) == nil {
				t.Fatal("old authority transferred")
			}
			tampered := old.verified.Snapshot()
			tampered[packagev3.WorkflowPath] = bytes.Clone(fresh.options.WorkflowYAML)
			if _, err := packagev3.Verify(context.Background(), packagev3.VerifyOptions{Scope: old.options.Scope, ExpectedSHA256: old.verified.SHA256(), Files: tampered}); err == nil {
				t.Fatal("timeout tamper verified")
			}
			t.Logf("source-fixture version=%s rebuilt=30->31 old_workflow=%s fresh_workflow=%s old_plan=%s fresh_plan=%s stale_plan_constraints_receipt_config_authority_refused=true tamper_refused=true effect_callbacks=0", version, old.packageBytes.Manifest.Workflow.SHA256, fresh.packageBytes.Manifest.Workflow.SHA256, oldPlan.PlanSHA256, freshPlan.PlanSHA256)
		})
	}
}

func requireInvalidPlan(t *testing.T, err error) {
	t.Helper()
	var refusal *execute.Refusal
	if !errors.As(err, &refusal) || refusal.Code != execute.InvalidPlan {
		t.Fatal("want actual native invalid_plan", err)
	}
}

func TestP12UntimedPublicHistoryRetainedAndNativeRefusalBeforeSourceRead(t *testing.T) {
	for _, version := range []string{"1.0", "1.1"} {
		t.Run(version, func(t *testing.T) {
			f := newJointFixture(t, version, "")
			history, err := packagev3.InspectHistory(context.Background(), packagev3.HistoryRequest{FormatVersion: packagev3.PackageVersion, Scope: f.options.Scope, ExpectedSHA256: f.verified.SHA256(), Files: f.verified.Snapshot()})
			if err != nil || !history.ReadOnly || history.SourceProof {
				t.Fatal("untimed history changed", err)
			}
			_, _, err = f.nativeCompile(context.Background(), browsercontract.SHA256([]byte("P12 untimed preparation")), browsercontract.SHA256([]byte("P12 untimed receipt; no authority")))
			requireInvalidPlan(t, err)
			if f.lastSourceReads != 0 {
				t.Fatal("untimed compile read sources")
			}
			execution := f.execution()
			if _, err := packagev3.DeriveExecutionPlan(context.Background(), f.verified, execution); err == nil || f.admissions != 1 {
				t.Fatal("untimed native refusal did not propagate")
			}
			requireInvalidPlan(t, f.lastAdmission)
			if f.lastSourceReads != 0 || !bytes.Equal(f.verified.Snapshot()[packagev3.WorkflowPath], f.options.WorkflowYAML) || strings.Contains(string(f.options.WorkflowYAML), "timeout:") {
				t.Fatal("untimed bytes or early refusal changed")
			}
			// Genuine CheckSupported revalidation of an exposed timed native
			// document rejects removal of the required timeout before source access.
			timed := newJointFixture(t, version, "30")
			plan, host, err := timed.nativeCompile(context.Background(), browsercontract.SHA256([]byte("P12 timed preparation")), browsercontract.SHA256([]byte("P12 timed receipt; no authority")))
			if err != nil {
				t.Fatal(err)
			}
			before := len(host.Sources.(*pureSources).refs)
			plan.Document().Operations[0].Timeout = nil
			err = execute.CheckSupported(context.Background(), execute.Request{Plan: plan}, host)
			requireInvalidPlan(t, err)
			if len(host.Sources.(*pureSources).refs) != before {
